CREATE TABLE public.marca_recurrence_cancellations(subscription_id uuid PRIMARY KEY REFERENCES public.master_subscriptions(id),store_id uuid NOT NULL,provider_reference text NOT NULL,state text NOT NULL DEFAULT 'ready' CHECK(state IN('ready','processing','sent','unknown','completed')),claim_token uuid,claimed_at timestamptz,actor_id uuid,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.marca_recurrence_cancellations TO service_role;
REVOKE ALL ON public.marca_recurrence_cancellations FROM anon,authenticated;
ALTER TABLE public.marca_recurrence_cancellations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_marca_recurrence_cancellation(p_actor uuid,p_store_id uuid,p_subscription_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.master_subscriptions;op public.marca_recurrence_cancellations;tok uuid:=gen_random_uuid();BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR NOT has_role(p_actor,'admin') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;SELECT * INTO s FROM master_subscriptions WHERE id=p_subscription_id AND user_id=p_store_id FOR UPDATE;IF NOT FOUND OR s.gateway<>'mercadopago' OR s.gateway_subscription_id IS NULL OR lower(s.plan_id) NOT IN('premium','pro') THEN RAISE EXCEPTION 'subscription_mismatch';END IF;IF NOT EXISTS(SELECT 1 FROM brand_account_owned_stores WHERE store_profile_id=p_store_id AND store_role='secondary') OR get_brand_inherited_plan(p_store_id) IS DISTINCT FROM 'marca' THEN RAISE EXCEPTION 'no_marca_fallback';END IF;INSERT INTO marca_recurrence_cancellations(subscription_id,store_id,provider_reference) VALUES(s.id,p_store_id,s.gateway_subscription_id) ON CONFLICT DO NOTHING;SELECT * INTO op FROM marca_recurrence_cancellations WHERE subscription_id=s.id FOR UPDATE;IF op.provider_reference<>s.gateway_subscription_id OR op.store_id<>p_store_id THEN RAISE EXCEPTION 'operation_mismatch';END IF;IF op.state='completed' THEN RETURN jsonb_build_object('claimed',false,'completed',true,'result',op.result);END IF;IF op.state IN('sent','unknown') OR(op.state='processing' AND op.claimed_at<now()-interval '1 minute') THEN IF op.claimed_at>now()-interval '1 minute' THEN RETURN jsonb_build_object('claimed',false,'processing',true);END IF;UPDATE marca_recurrence_cancellations SET state='unknown',claim_token=tok,claimed_at=now(),actor_id=p_actor,updated_at=now() WHERE subscription_id=s.id;RETURN jsonb_build_object('claimed',true,'reconcile_only',true,'token',tok,'provider_reference',s.gateway_subscription_id,'paid_until',s.current_period_end,'local_status',s.status);END IF;IF op.state='processing' THEN RETURN jsonb_build_object('claimed',false,'processing',true);END IF;UPDATE marca_recurrence_cancellations SET state='processing',claim_token=tok,claimed_at=now(),actor_id=p_actor,updated_at=now() WHERE subscription_id=s.id;RETURN jsonb_build_object('claimed',true,'reconcile_only',false,'token',tok,'provider_reference',s.gateway_subscription_id,'paid_until',s.current_period_end,'local_status',s.status);END $$;
CREATE FUNCTION public.mark_marca_recurrence_cancellation_sent(p_subscription_id uuid,p_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE op public.marca_recurrence_cancellations;BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;SELECT * INTO op FROM marca_recurrence_cancellations WHERE subscription_id=p_subscription_id FOR UPDATE;IF NOT FOUND OR op.claim_token IS DISTINCT FROM p_token OR op.state<>'processing' THEN RAISE EXCEPTION 'stale_claim';END IF;IF NOT has_role(op.actor_id,'admin') OR NOT EXISTS(SELECT 1 FROM brand_account_owned_stores WHERE store_profile_id=op.store_id AND store_role='secondary') OR get_brand_inherited_plan(op.store_id) IS DISTINCT FROM 'marca' THEN RAISE EXCEPTION 'no_marca_fallback';END IF;UPDATE marca_recurrence_cancellations SET state='sent',updated_at=now() WHERE subscription_id=p_subscription_id;END $$;
CREATE FUNCTION public.complete_marca_recurrence_cancellation(p_subscription_id uuid,p_token uuid,p_before text,p_after text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE op public.marca_recurrence_cancellations;s public.master_subscriptions;r jsonb;BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR p_after IS DISTINCT FROM 'cancelled' THEN RAISE EXCEPTION 'unconfirmed_cancellation';END IF;SELECT * INTO op FROM marca_recurrence_cancellations WHERE subscription_id=p_subscription_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'stale_claim';END IF;IF op.state='completed' THEN RETURN op.result;END IF;IF op.claim_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'stale_claim';END IF;SELECT * INTO s FROM master_subscriptions WHERE id=p_subscription_id;r:=jsonb_build_object('ok',true,'before',jsonb_build_object('status',p_before),'after',jsonb_build_object('status','cancelled'),'paid_until',s.current_period_end,'local_status',s.status);INSERT INTO master_subscription_logs(subscription_id,user_id,event_type,event_description,metadata) VALUES(s.id,op.store_id,'external_recurrence_cancelled_marca_secondary','Recorrência externa encerrada após vínculo MARCA; período já pago preservado até o fim.',jsonb_build_object('provider_status_before',p_before,'provider_status_after','cancelled','paid_until',s.current_period_end,'actor',op.actor_id));UPDATE marca_recurrence_cancellations SET state='completed',result=r,updated_at=now() WHERE subscription_id=s.id;RETURN r;END $$;
CREATE FUNCTION public.fail_marca_recurrence_cancellation(p_subscription_id uuid,p_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;UPDATE marca_recurrence_cancellations SET state=CASE WHEN state='processing' THEN 'ready' ELSE 'unknown' END,claim_token=NULL,claimed_at=now(),updated_at=now() WHERE subscription_id=p_subscription_id AND claim_token=p_token AND state<>'completed';END $$;
REVOKE ALL ON FUNCTION public.claim_marca_recurrence_cancellation(uuid,uuid,uuid),public.mark_marca_recurrence_cancellation_sent(uuid,uuid),public.complete_marca_recurrence_cancellation(uuid,uuid,text,text),public.fail_marca_recurrence_cancellation(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_marca_recurrence_cancellation(uuid,uuid,uuid),public.mark_marca_recurrence_cancellation_sent(uuid,uuid),public.complete_marca_recurrence_cancellation(uuid,uuid,text,text),public.fail_marca_recurrence_cancellation(uuid,uuid) TO service_role;